def rectangle_intersection_area(r1, r2):
    x_overlap = max(r1[0], r2[0])
    x_overlap_end = min(r1[2], r2[2])
    y_overlap = max(r1[1], r2[1])
    y_overlap_end = min(r1[3], r2[3])
    if x_overlap < x_overlap_end and y_overlap < y_overlap_end:
        return (x_overlap_end - x_overlap) * (y_overlap_end - y_overlap)
    else:
        return 0
